def clean(s):return s.replace('{','').replace('}','').replace('---','—').replace('--','–')

def main():
    assert len(rows)==21 and len({r[0] for r in rows})==21 and len({r[8].lower() for r in rows})==21
    prefix=OUT/'references_user_verified_20261029'
    bib=['% Verified against publisher/author records on 2026-10-29.','% All 21 user-supplied items retained in original order; the last three were supplied by Jake.','% Verification of existence and metadata is not a study-quality assessment.','']
    readable=['Verified references supplied by the user','Checked: 29 October 2026','21 located works: 20 journal articles and one arXiv preprint.','Original order retained; [19]–[21] were the three suggestions from Jake.','']
    audit=[]
    for n,row in enumerate(rows,1):
        key,authors,year,title,journal,vol,num,pages,doi,source,note=row
        preprint=n==21
        fields={'author':authors,'title':'{'+title+'}','year':str(year)}
        if preprint:fields.update(eprint='2512.02406',archivePrefix='arXiv',primaryClass='cs.LG',note='Preprint')
        else:fields['journal']=journal
        if vol:fields['volume']=vol
        if num:fields['number']=num
        if pages:fields['pages']=pages
        fields.update(doi=doi,url='https://doi.org/'+doi)
        if n==9:fields['note']='Advance online publication'
        bib+=['@'+('misc' if preprint else 'article')+'{'+key+',']+['  '+k+' = {'+v+'},' for k,v in fields.items()]+['}','']
        venue=journal+(f', {vol}' if vol else '')+(f'({num})' if num else '')+(f', {clean(pages)}' if pages else '')
        if n==9:venue+='; advance online publication'
        if preprint:venue='arXiv:2512.02406 [preprint]'
        readable += [f'[{n}] {clean(authors.replace(" and ", "; "))} ({year}). {clean(title)}. {venue}. https://doi.org/{doi}','']
        audit.append(dict(number=n,key=key,exists_verified=True,publication_type='preprint' if preprint else 'journal article',doi=doi,evidence_url=source,verification_note=note))
    prefix.with_suffix('.bib').write_text('\n'.join(bib),encoding='utf-8')
    prefix.with_suffix('.txt').write_text('\n'.join(readable),encoding='utf-8')
    log=['# Reference verification record','', 'Checked 29 October 2026 against the exact pasted list, including all three Jake suggestions. All 21 works were located. This file verifies bibliographic existence and records metadata corrections; it does not certify the quality, conclusions, or suitability of every study.','', '## Corrections and qualifications','', '- Added the missing DOI for [8]: `10.1016/j.tra.2025.104542`.','- Added volume/pages for [10], final indexed issue details for [14], full authors for [15]/[16], and article number for [16].','- Repaired punctuation artifacts in titles, hyphenated names, and page ranges.','- Kept issue years distinct from online-publication and DOI years, especially [3], [7], [14], and [20].','- [9] remains advance online publication: no unverified final volume or pages were invented.','- [21] remains a preprint; it was not presented as a peer-reviewed journal article.','- Some direct publisher/DOI requests were blocked. Publisher search-index records, author-hosted manuscripts and institutional records were used where available; [14] final issue coordinates were corroborated through TRID rather than a directly accessible IEEE page.','- References older than 2020 were retained because this exact user-supplied list explicitly included them.','', '| Original item | Citation key | Existence evidence | Correction / qualification |','|---|---|---|---|']
    for a in audit:log.append(f'| {a["number"]} | `{a["key"]}` | [Located record]({a["evidence_url"]}) | {a["verification_note"]} |')
    log+=['','## Using the new file','','```latex','\\bibliographystyle{IEEEtran}','\\bibliography{references_user_verified_20261029}','```','','This is a new library, not an overwrite of `references.bib`. Cite only sources actually used in the manuscript. The supplied list did not include Cao et al. (2024) or the recent parking digital-twin papers from the earlier working library; they were not silently appended. The two libraries share some citation keys, so do not load both indiscriminately without deduplication.']
    (OUT/'reference_verification_20261029.md').write_text('\n'.join(log)+'\n',encoding='utf-8')
    payload=dict(checked_on='2026-10-29',scope='21 items in user attachment, original order',references=audit)
    payload['output_sha256']={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in [prefix.with_suffix('.bib'),prefix.with_suffix('.txt'),OUT/'reference_verification_20261029.md']}
    (OUT/'reference_verification_20261029.json').write_text(json.dumps(payload,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    text=prefix.with_suffix('.bib').read_text(encoding='utf-8')
    assert len(re.findall(r'^@',text,re.M))==21
    assert text.count('{')==text.count('}')
    print('Created corrected .bib and readable .txt: 21 entries; unique keys/DOIs and balanced braces checked.')

if __name__=='__main__':main()
